    // [seed arx]
    std::uint8_t *aSource = pWorkSpace->mSource;
    READ_IN_MUTABLE_PARAMS;
    [[maybe_unused]] const std::uint64_t aNonceWordA = TwistMix64::DiffuseA(pNonce * 0xB7FBA83ABF3B9145ULL + 0xF79EB9DD2F12B75AULL);
    [[maybe_unused]] const std::uint64_t aNonceWordB = TwistMix64::DiffuseA(pNonce * 0xD3A63BE4EE46312BULL + 0x99D18894EF34E69AULL);
