            //
            aOrbiterJ = (aOrbiterJ + aOrbiterI) + 0x524187345A3C440DULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterJ) ^ 0x177F08B28666433AULL) ^ aTwistOrbiterUpdateSaltE[((aIndex + 17U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0xA68D39D8FECA44D9ULL), 35U);
