            aOrbiterI = (((aWandererA + RotL64(aScatter, 47U)) + RotL64(aCarry, 21U)) + 0x1A524FDB359C76A9ULL) + aTwistOrbiterAssignSaltB[((aIndex + 4U)) & S_SALT1];
            aOrbiterE = (aWandererG + RotL64(aCross, 51U)) + 0xD438195BED58539BULL;
            aOrbiterG = ((aWandererK + RotL64(aPrevious, 35U)) + 0x5E86605298EC8338ULL) + aTwistOrbiterAssignSaltF[((aIndex + 7U)) & S_SALT1];
            aOrbiterB = ((aWandererJ + RotL64(aIngress, 5U)) + RotL64(aCarry, 57U)) + 0x798733FA8C7A7854ULL;
            aOrbiterA = (aWandererF + RotL64(aCross, 24U)) + 0x2AD76A7E16E2D11EULL;
            aOrbiterC = (aWandererI + RotL64(aScatter, 43U)) + 0x581DCC2FDE1EFE1BULL;
            aOrbiterF = (aWandererD + RotL64(aCross, 29U)) + 0x9E7D3822B61859D0ULL;
            //
            aOrbiterK = (aOrbiterK + aOrbiterD) + 0x3AE261E7145E49EBULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterK) ^ 0xB59499E4E351FB94ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x10E8505447E34D15ULL), 29U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterG) + 0x79A7307B9C716406ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterE) ^ 0xBE850C1EB1BB50A4ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x820DD9C410D5EBA7ULL), 19U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterA) + 0x73F44C0C57DA4AE7ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterB) ^ 0xDEE75F3ADB59572AULL;
            aOrbiterC = RotL64((aOrbiterC * 0x72146B1E117E880DULL), 47U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterB) + 0x881ED04CF055DF86ULL) + aTwistOrbiterUpdateSaltC[((aIndex + 23U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterI) ^ 0x53485FAD532F6BB0ULL;
            aOrbiterG = RotL64((aOrbiterG * 0xD607EB56AE2FCA09ULL), 37U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterE) + 0x50F4ABE0D10A3C6AULL) + aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 19U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterC) ^ 0x31942E567D4483BAULL;
            aOrbiterK = RotL64((aOrbiterK * 0x1349677DC19168EBULL), 23U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterI) + 0xBF815EF7180B46A3ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterA) ^ 0xC4B904CEB3CF4A39ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x5E2A24F362055305ULL), 51U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterC) + 0xE2CFD1DB596B9537ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterG) ^ 0x5A6164B29BBA09A9ULL;
