            aCross = TwistMix64::DiffuseB((aCross ^ aTwistDomainWordCross));
            //
            aScatter = (RotL64(aCarry, 57U) + RotL64(aIngress, 39U)) ^ (RotL64(aPrevious, 5U) + RotL64(aCross, 20U));
