            //
            aOrbiterA = ((aWandererI + RotL64(aIngress, 51U)) + RotL64(aCarry, 5U)) + 0x0F2A6B025E987AE1ULL;
            aOrbiterC = (aWandererA + RotL64(aPrevious, 43U)) + 0x3F7D8C1A030B6D37ULL;
            aOrbiterG = (aWandererK + RotL64(aCross, 19U)) + 0x9454090BE16F3272ULL;
            aOrbiterE = ((aWandererG + RotL64(aScatter, 13U)) + RotL64(aCarry, 53U)) + 0x1731C9A6CAFD4584ULL;
            aOrbiterH = ((aWandererB + RotL64(aCross, 37U)) + 0x51708B8C86EBDE86ULL) + aTwistOrbiterAssignSaltE[(((31U - aIndex) + 13U)) & S_SALT1];
            aOrbiterB = ((aWandererD + RotL64(aPrevious, 28U)) + RotL64(aCarry, 35U)) + 0x292833E9538B3B1EULL;
            aOrbiterI = ((aWandererH + RotL64(aScatter, 57U)) + 0x49027B950862FB2CULL) + aTwistOrbiterAssignSaltA[(((31U - aIndex) + 12U)) & S_SALT1];
