            //
            aOrbiterE = (aOrbiterE + aOrbiterG) + 0xF1525E81CA42C1A7ULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterE) ^ 0x4643F8429792404CULL) ^ aTwistOrbiterUpdateSaltB[(((31U - aIndex) + 3U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0xC33E090616EF996FULL), 27U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterE) + 0x1A646A04DB6606E4ULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterB) ^ 0x51D6669A301E768AULL) ^ aTwistOrbiterUpdateSaltD[(((31U - aIndex) + 8U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0xEA8CC336EA2E559BULL), 35U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterI) + 0x1D43D872066547AAULL) + aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterG) ^ 0x6D4551515AD5572CULL;
            aOrbiterB = RotL64((aOrbiterB * 0x644E3B5812ACAAE9ULL), 47U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterH) + 0x30E5C135DB530F95ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterC) ^ 0x63445C427283287BULL;
            aOrbiterI = RotL64((aOrbiterI * 0xEEC40E3BE2EFBB7BULL), 3U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterB) + 0xE981372EC235228EULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterH) ^ 0x3B7E83C7C5AF35E4ULL) ^ aTwistOrbiterUpdateSaltC[((aIndex + 21U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0xD02CB3AC0D545613ULL), 21U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterA) + 0xC8C8E17F2F9B1B31ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterI) ^ 0x2A321A59CC58BD06ULL;
            aOrbiterE = RotL64((aOrbiterE * 0xEB1387A58EFB6795ULL), 11U);
            //
            aIngress = RotL64(aOrbiterI, 11U) ^ aOrbiterC;
