            //
            aWandererK = aWandererK + ((((RotL64(aCross, 5U) + RotL64(aOrbiterC, 29U)) + aOrbiterA) + RotL64(aCarry, 43U)) + aTwistWandererUpdateSaltE[(((31U - aIndex) + 28U)) & S_SALT1]);
