        //      aFuseLaneA (-->), aWaterLaneC (-->), pCrossLaneB (-->), aFireLaneB (<-?->)
        //
        // Cross:
        //      aWaterLaneA (<--), aWaterLaneD (<--), aEarthLaneC (<--), aSource (<-?->)
        //
