            aCross = TwistMix64::DiffuseA((aCross ^ aTwistDomainWordCross));
            //
            aScatter = (RotL64(aPrevious, 3U) + RotL64(aCross, 35U)) + (RotL64(aIngress, 48U) ^ RotL64(aCarry, 19U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterE = (aWandererD + RotL64(aCross, 47U)) + 0xA834E8539ACD1C9CULL;
            aOrbiterA = (aWandererK + RotL64(aIngress, 35U)) + 0x1DFBB20DEB1EDD6CULL;
            aOrbiterG = (((aWandererA + RotL64(aScatter, 19U)) + RotL64(aCarry, 35U)) + 0x8AD78F9CE5347377ULL) + aTwistOrbiterAssignSaltF[(((31U - aIndex) + 28U)) & S_SALT1];
            aOrbiterI = (((aWandererH + RotL64(aPrevious, 27U)) + RotL64(aCarry, 19U)) + 0xFDDDF41A926F4EC1ULL) + aTwistOrbiterAssignSaltB[(((31U - aIndex) + 6U)) & S_SALT1];
            aOrbiterK = (aWandererG + RotL64(aIngress, 41U)) + 0x53244B0C60EEE022ULL;
            aOrbiterF = ((aWandererE + RotL64(aCross, 10U)) + RotL64(aCarry, 3U)) + 0xF53B35C3BC45E5BDULL;
            aOrbiterH = (aWandererI + RotL64(aScatter, 3U)) + 0x3D7CA95D3B9865B6ULL;
            //
            aOrbiterE = (aOrbiterE + aOrbiterA) + 0xEF4A8DCD7CBB146CULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterE) ^ 0xF227B2BD40BD6064ULL) ^ aTwistOrbiterUpdateSaltD[(((31U - aIndex) + 9U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0x61ED6B8C151BDC33ULL), 47U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterK) + 0xDB1D83B1AC64797AULL) + aTwistOrbiterUpdateSaltB[((aIndex + 4U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterI) ^ 0x32C190121B5B0DF2ULL;
            aOrbiterA = RotL64((aOrbiterA * 0xA02C3DD97A981513ULL), 13U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterF) + 0x36A70CD96F302FBFULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterG) ^ 0x92EC4CC433F98797ULL;
            aOrbiterK = RotL64((aOrbiterK * 0xC3EC84F1A6E12055ULL), 27U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterE) + 0x639B2C93E11974B1ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterK) ^ 0x0A46C223BE8FC8B8ULL;
            aOrbiterH = RotL64((aOrbiterH * 0xE530421322952321ULL), 37U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterH) + 0x88110C4609E3618EULL) + aTwistOrbiterUpdateSaltA[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterA) ^ 0x776A5660E060ECAFULL;
            aOrbiterF = RotL64((aOrbiterF * 0x248E034DD94CD079ULL), 3U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterI) + 0xB5B45890D3B2EA5EULL) + aTwistOrbiterUpdateSaltE[(((31U - aIndex) + 3U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterF) ^ 0x1C8279A0F17E9A47ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x78F79E81DF2A32E9ULL), 21U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterG) + 0xC816EFD03D8834AFULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterH) ^ 0x79A8C8A0EE26E610ULL;
