            //
            aWandererA = aWandererA ^ ((RotL64(aCross, 35U) + aOrbiterG) + RotL64(aOrbiterE, 19U));
            aWandererD = aWandererD + ((RotL64(aPrevious, 20U) + RotL64(aOrbiterI, 51U)) + aOrbiterK);
            aWandererK = aWandererK ^ ((RotL64(aScatter, 13U) + aOrbiterH) + RotL64(aOrbiterF, 27U));
