            aCross = (RotL64(aFuseLaneA[((S_BLOCK1 - aIndex + 21376U)) & S_BLOCK1], 35U) ^ RotL64(aWaterLaneB[((S_BLOCK1 - aIndex + 22859U)) & S_BLOCK1], 54U));
            aCross ^= RotL64(pCrossLaneC[((S_BLOCK1 - aIndex + 22627U)) & S_BLOCK1], 11U);
