            aScatter = (RotL64(aPrevious, 60U) ^ RotL64(aCarry, 11U)) + (RotL64(aIngress, 39U) + RotL64(aCross, 23U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterK = (aWandererF + RotL64(aPrevious, 5U)) + 0x60D22304229251F9ULL;
            aOrbiterE = ((aWandererJ + RotL64(aIngress, 28U)) + RotL64(aCarry, 29U)) + 0xC214585EC81AEF4AULL;
            aOrbiterC = (aWandererE + RotL64(aScatter, 19U)) + 0x6D7589886DCC72A1ULL;
            aOrbiterB = ((aWandererH + RotL64(aCross, 57U)) + 0x69CBCE2A66C1A5D7ULL) + aTwistOrbiterAssignSaltD[((aIndex + 24U)) & S_SALT1];
            aOrbiterD = (((aWandererK + RotL64(aScatter, 13U)) + RotL64(aCarry, 41U)) + 0x12BCD6A83B6EDF09ULL) + aTwistOrbiterAssignSaltC[((aIndex + 11U)) & S_SALT1];
            aOrbiterI = (aWandererI + RotL64(aCross, 39U)) + 0x2993C09CFA91B995ULL;
            aOrbiterH = ((aWandererG + RotL64(aPrevious, 51U)) + RotL64(aCarry, 11U)) + 0xA46F561D8BDAA5A5ULL;
            //
            aOrbiterK = (aOrbiterK + aOrbiterE) + 0xE557C3079CE87240ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterK) ^ 0x3D0B106593BAA9F1ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x1162730222C775BFULL), 13U);
