            aCross = (RotL64(aWoodLaneC[((S_BLOCK1 - aIndex + 4135U)) & S_BLOCK1], 12U) ^ RotL64(aWoodLaneD[((S_BLOCK1 - aIndex + 5118U)) & S_BLOCK1], 29U));
