            aOrbiterH = (aWandererJ + RotL64(aIngress, 21U)) + 0x7B39C16FD82A83C0ULL;
            aOrbiterB = ((aWandererE + RotL64(aCross, 35U)) + RotL64(aCarry, 29U)) + 0xD2633DD3DAB2AD28ULL;
            aOrbiterF = ((aWandererB + RotL64(aPrevious, 27U)) + RotL64(aCarry, 11U)) + 0x9B465CAD16B98FB3ULL;
            aOrbiterK = (aWandererD + RotL64(aScatter, 13U)) + 0x7B06F90AD3A08EB7ULL;
            aOrbiterA = ((aWandererI + RotL64(aCross, 56U)) + 0xC84B4C2F42CBEAA1ULL) + aTwistOrbiterAssignSaltB[((aIndex + 22U)) & S_SALT1];
            aOrbiterJ = (aWandererC + RotL64(aIngress, 41U)) + 0xC908CD9790DAF8DCULL;
            aOrbiterC = (((aWandererG + RotL64(aScatter, 3U)) + RotL64(aCarry, 47U)) + 0xAB6FA5283F4ABD15ULL) + aTwistOrbiterAssignSaltC[((aIndex + 13U)) & S_SALT1];
            //
            aOrbiterH = (aOrbiterH + aOrbiterB) + 0x470DEA3DB3DB6E93ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterH) ^ 0x4C8A10B1D3BA607BULL;
            aOrbiterF = RotL64((aOrbiterF * 0x119A1AC1DC829427ULL), 11U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterA) + 0x3A3D6C2930E3317FULL;
