            aOrbiterC = RotL64((aOrbiterC * 0x8AC29AE07DCDB0F7ULL), 23U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterI) + 0xCA1C67EC5310D7CBULL) + aTwistOrbiterUpdateSaltF[((aIndex + 25U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterG) ^ 0x191684349BE8F51AULL;
            aOrbiterK = RotL64((aOrbiterK * 0x998A568AD8A65169ULL), 3U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterC) + 0xC9C9A31250843165ULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterI) ^ 0xA0DE244C2F16C83DULL) ^ aTwistOrbiterUpdateSaltC[((aIndex + 21U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x4B3BF5346CD9A1D1ULL), 13U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterD) + 0x8FAF6744896BD443ULL;
