            aOrbiterE = RotL64((aOrbiterE * 0x03F463DE52850373ULL), 41U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterG) + 0xDBD2DD9BE9310ECEULL) + aTwistOrbiterUpdateSaltA[(((31U - aIndex) + 19U)) & S_SALT1];
