            //
            aWandererK = aWandererK ^ (((RotL64(aScatter, 34U) + RotL64(aOrbiterH, 29U)) + aOrbiterJ) + aTwistWandererUpdateSaltC[((aIndex + 9U)) & S_SALT1]);
            aWandererB = aWandererB + (((RotL64(aCross, 23U) + aOrbiterG) + RotL64(aOrbiterC, 6U)) + RotL64(aCarry, 35U));
            aWandererG = aWandererG ^ (((RotL64(aPrevious, 19U) + RotL64(aOrbiterJ, 11U)) + aOrbiterK) + aTwistWandererUpdateSaltF[(((31U - aIndex) + 22U)) & S_SALT1]);
