            aWandererC = aWandererC ^ ((RotL64(aIngress, 44U) + RotL64(aOrbiterD, 23U)) + aOrbiterB);
            aWandererH = aWandererH + (((RotL64(aScatter, 57U) + aOrbiterE) + RotL64(aOrbiterG, 44U)) + RotL64(aCarry, 43U));
            aWandererE = aWandererE ^ ((RotL64(aPrevious, 51U) + aOrbiterJ) + RotL64(aOrbiterB, 19U));
