            aOrbiterH = (aWandererB + RotL64(aCross, 34U)) + 0xB493A5E279BDBCA9ULL;
            aOrbiterD = ((aWandererD + RotL64(aPrevious, 53U)) + RotL64(aCarry, 37U)) + 0xCA8D2B1205854C10ULL;
            aOrbiterK = (aWandererJ + RotL64(aIngress, 5U)) + 0xA6F6A75F51B6E0CFULL;
            aOrbiterA = ((aWandererG + RotL64(aCross, 29U)) + RotL64(aCarry, 21U)) + 0x51D11076A3A742D6ULL;
            aOrbiterC = (aWandererF + RotL64(aPrevious, 13U)) + 0x642A6C5BC6B02B58ULL;
            aOrbiterI = (((aWandererC + RotL64(aIngress, 47U)) + RotL64(aCarry, 57U)) + 0x80DD7A958C4AAF87ULL) + aKeyRotateAOrbiterAssignSaltB[(((31U - aIndex) + 4U)) & S_SALT1];
