            aOrbiterB = ((aWandererA + RotL64(aPrevious, 60U)) + 0x28FCA08D105F7036ULL) + aKeyRotateAOrbiterAssignSaltE[((aIndex + 8U)) & S_SALT1];
            //
            aOrbiterF = (aOrbiterF + aOrbiterH) + 0x543E96185BBAFBB2ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterF) ^ 0xD84CE16B2840CD3AULL;
            aOrbiterD = RotL64((aOrbiterD * 0xF9225AFBC66AD09DULL), 57U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterK) + 0x17B5B9CC62F90BB8ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterH) ^ 0x733F726284EBB547ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x8D4CCEE9347E8B5BULL), 37U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterA) + 0xF5BD7419EDBB0A61ULL;
