            aOrbiterH = ((aOrbiterH ^ aOrbiterI) ^ 0x776424D4E59471CEULL) ^ aKeyRotateAOrbiterUpdateSaltE[(((31U - aIndex) + 29U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x41D8EC31C87ED961ULL), 21U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterI) + 0x8F67DA63EDD4A24BULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterJ) ^ 0xE86A9A73D9659231ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x9BCF4EE8346F63EFULL), 11U);
