            aIngress = TwistMix64::DiffuseB((aIngress + aScatter));
            //
            aWandererJ = aWandererJ ^ ((RotL64(aIngress, 51U) + aOrbiterD) + RotL64(aOrbiterE, 56U));
            aWandererD = aWandererD + ((RotL64(aCross, 27U) + aOrbiterA) + RotL64(aOrbiterG, 3U));
            aWandererE = aWandererE ^ ((RotL64(aScatter, 43U) + RotL64(aOrbiterG, 37U)) + aOrbiterK);
            aWandererF = aWandererF + ((RotL64(aPrevious, 23U) + aOrbiterC) + RotL64(aOrbiterI, 41U));
            aWandererC = aWandererC ^ (((RotL64(aCross, 39U) + RotL64(aOrbiterC, 39U)) + aOrbiterH) + aKeyRotateAWandererUpdateSaltA[((aIndex + 15U)) & S_SALT1]);
            aWandererH = aWandererH + (((RotL64(aPrevious, 41U) + aOrbiterA) + RotL64(aOrbiterC, 60U)) + RotL64(aCarry, 43U));
            aWandererA = aWandererA ^ (((RotL64(aIngress, 46U) + RotL64(aOrbiterJ, 23U)) + aOrbiterC) + aKeyRotateAWandererUpdateSaltB[(((31U - aIndex) + 21U)) & S_SALT1]);
            aWandererI = aWandererI + ((RotL64(aScatter, 21U) + RotL64(aOrbiterE, 5U)) + aOrbiterH);
            aWandererK = aWandererK ^ ((RotL64(aIngress, 37U) + aOrbiterE) + RotL64(aOrbiterF, 13U));
            aWandererB = aWandererB + (((RotL64(aScatter, 53U) + RotL64(aOrbiterC, 35U)) + aOrbiterB) + RotL64(aCarry, 29U));
            aWandererG = aWandererG ^ ((RotL64(aPrevious, 48U) + aOrbiterF) + RotL64(aOrbiterA, 19U));
            //
            aCarry = aCarry + (aWandererH ^ RotL64(aWandererE, 53U));
