            aOrbiterI = (aWandererD + RotL64(aIngress, 4U)) + 0x0E5BEA20B3EE0909ULL;
            aOrbiterA = (((aWandererJ + RotL64(aPrevious, 57U)) + RotL64(aCarry, 51U)) + 0x9B8BE8A9D8A33E91ULL) + aKeyRotateAOrbiterAssignSaltD[((aIndex + 11U)) & S_SALT1];
            aOrbiterD = (aWandererK + RotL64(aCross, 21U)) + 0xD5554B4D3E895859ULL;
