            //
            aOrbiterE = ((aOrbiterE + aOrbiterI) + 0xB683DAA4D453D3D4ULL) + aKeyRotateAOrbiterUpdateSaltB[(((31U - aIndex) + 26U)) & S_SALT1];
            aOrbiterA = ((aOrbiterA ^ aOrbiterE) ^ 0xD0B927A67B64DB3DULL) ^ aKeyRotateAOrbiterUpdateSaltD[(((31U - aIndex) + 4U)) & S_SALT1];
