            //
            aScatter = (RotL64(aIngress, 23U) ^ RotL64(aCarry, 39U)) + (RotL64(aCross, 54U) + RotL64(aPrevious, 5U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterK = (aWandererJ + RotL64(aCross, 60U)) + 0xC3978151850BC887ULL;
            aOrbiterA = ((aWandererI + RotL64(aIngress, 51U)) + 0xECA7BAEF707AF922ULL) + aKeyRotateAOrbiterAssignSaltC[(((31U - aIndex) + 4U)) & S_SALT1];
            aOrbiterE = ((aWandererF + RotL64(aScatter, 21U)) + RotL64(aCarry, 23U)) + 0xF8555D10ED0DBA19ULL;
            aOrbiterJ = (((aWandererC + RotL64(aPrevious, 43U)) + RotL64(aCarry, 5U)) + 0x36F0826BC6699D78ULL) + aKeyRotateAOrbiterAssignSaltA[(((31U - aIndex) + 5U)) & S_SALT1];
            aOrbiterD = ((aWandererA + RotL64(aCross, 5U)) + RotL64(aCarry, 37U)) + 0xAF9936219BE89C5FULL;
            aOrbiterC = (aWandererH + RotL64(aIngress, 11U)) + 0x868ADEE27A353158ULL;
            aOrbiterG = (aWandererK + RotL64(aScatter, 29U)) + 0xF9839D89FA6ED5B8ULL;
            //
            aOrbiterK = (aOrbiterK + aOrbiterA) + 0x64BB0D8DAE507213ULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterK) ^ 0xB1EEE59F202644F3ULL) ^ aKeyRotateAOrbiterUpdateSaltA[(((31U - aIndex) + 7U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0xED56BA08EC4DCE2FULL), 11U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterK) + 0x027D55E852115B2BULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterJ) ^ 0x4FADF668313F33D4ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x689033972D75E62FULL), 43U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterJ) + 0x63A826F1077A6A3EULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterC) ^ 0x48C62E4771A0734EULL) ^ aKeyRotateAOrbiterUpdateSaltC[((aIndex + 27U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0x249A2DB65C92B22BULL), 27U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterC) + 0x92098F6780CDC17EULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterG) ^ 0x1F104E599E91220BULL) ^ aKeyRotateAOrbiterUpdateSaltF[(((31U - aIndex) + 22U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0xDA70C6DA99845EE1ULL), 57U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterG) + 0xF3BF1EB2067442C1ULL) + aKeyRotateAOrbiterUpdateSaltE[(((31U - aIndex) + 3U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterE) ^ 0xE17726FB2CF84B62ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x595F082F9756BB21ULL), 35U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterD) + 0xF2C94C8DCFB74BE2ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterA) ^ 0xEFBEC09B2E0D9A39ULL;
            aOrbiterG = RotL64((aOrbiterG * 0xC32C3DBAFD13123BULL), 51U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterE) + 0x1F8A5198669FBAABULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterD) ^ 0xDC7F22FD11AC2086ULL;
            aOrbiterC = RotL64((aOrbiterC * 0xA84BAF75C1FB7DEFULL), 19U);
            //
            aIngress = aOrbiterC ^ RotL64(aOrbiterK, 35U);
            aIngress = aIngress + (aOrbiterG ^ RotL64(aOrbiterE, 21U));
            aIngress = aIngress + (RotL64(aOrbiterD, 3U) ^ aOrbiterJ);
