            //
            aWandererC = aWandererC + (((RotL64(aIngress, 3U) + aOrbiterK) + RotL64(aOrbiterJ, 3U)) + RotL64(aCarry, 37U));
            aWandererK = aWandererK ^ (((RotL64(aCross, 13U) + RotL64(aOrbiterD, 39U)) + aOrbiterC) + aKeyRotateAWandererUpdateSaltF[((aIndex + 17U)) & S_SALT1]);
            aWandererA = aWandererA + ((RotL64(aScatter, 19U) + aOrbiterK) + RotL64(aOrbiterE, 29U));
            aWandererF = aWandererF ^ ((RotL64(aPrevious, 27U) + aOrbiterK) + RotL64(aOrbiterG, 13U));
            aWandererI = aWandererI + ((((RotL64(aScatter, 57U) + RotL64(aOrbiterC, 57U)) + aOrbiterE) + RotL64(aCarry, 19U)) + aKeyRotateAWandererUpdateSaltA[((aIndex + 24U)) & S_SALT1]);
            aWandererJ = aWandererJ ^ ((RotL64(aCross, 42U) + RotL64(aOrbiterA, 47U)) + aOrbiterG);
