            aOrbiterJ = ((aWandererD + RotL64(aIngress, 43U)) + RotL64(aCarry, 43U)) + 0x38E376FBE54A4578ULL;
            aOrbiterE = (aWandererA + RotL64(aCross, 29U)) + 0x513E177318743F34ULL;
            aOrbiterC = ((aWandererE + RotL64(aPrevious, 58U)) + RotL64(aCarry, 27U)) + 0x2639AE12C867186CULL;
            aOrbiterA = ((aWandererB + RotL64(aScatter, 51U)) + 0x6A873DA090F46F7FULL) + aKeyRotateBOrbiterAssignSaltB[(((31U - aIndex) + 9U)) & S_SALT1];
            aOrbiterH = ((aWandererG + RotL64(aIngress, 5U)) + 0xFC8314F0677346A4ULL) + aKeyRotateBOrbiterAssignSaltD[(((31U - aIndex) + 11U)) & S_SALT1];
